/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field noDiscountAllowed.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableNoDiscountAllowed extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, noDiscountAllowed);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Enum);
    RetailInventTable retailInventTable;
    while select noDiscountAllowed from retailInventTable
        group by noDiscountAllowed
    {
        ret.add(retailInventTable.noDiscountAllowed);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, noDiscountAllowed));
    qbr.value(queryValue(_value));
}
